ADDITIONS[19][11] = ('貴族院での重い選択まで','食事の席では、出発に必要な荷物が冬の前に他領へ送られていることも話題になりました。卒業式の頃に移る予定でも、雪が降れば通常の輸送は難しくなります。ローゼマインが境界まで運ぶ案なら可能ですが、領地の境で受け渡す条件も考えなければなりません。')
ADDITIONS[19][18] = ('南門を出た',ADDITIONS[19][18][1])
CLEANUPS[19][12].append(('鍵を開けられたなら、物を持ち出すだけでなく、触れた者を害する品を置くこともできます。',''))
