REPLACEMENTS[19][15] = ('怒りを制御する', '毒の仕込まれた偽物が、中身すらない空の魔術具だと分かった瞬間、ローゼマインの怒りは限界を越えます。大切な本を奪われ、身近な人々まで暗殺の危険にさらされた。その感情に呼応して、抑えていた魔力が一気にあふれかけました。視界を覆って止めたのはフェルディナンドです。彼は、過去にヴィルフリートが白の塔へ入った事件を例に出しました。今回も、一つの失敗から本人や周囲の者に不利な結果が向かうよう、幾つもの仕掛けが重なっています。怒りのまま犯人を追い、手順を誤れば、助けたい人まで処罰に巻き込むかもしれません。まず本物の聖典を取り戻し、戻らない場合にも被害を最小限にする。その目的を確認し、彼女に深呼吸させます。ローゼマインは暴れる魔力を押し戻しました。取り戻す必要はあるという点で二人の判断は一致していても、勢いだけで動くことはできません。フェルディナンドは側近たちにも、本と大切な身内が危険な時ほど、普段落ち着いた主が暴走すると教えました。命令を待つだけでなく、主を止めることも役目です。彼が見守っていたのは周囲から来る危険だけでなく、ローゼマイン自身が冷静さを失う時でもありました。騎士たちは、この役割まで引き継ぐ必要があると知ります。怒りを救出と捜査に使うため、主と側近が共に判断を保つ場面でした。')
CLEANUPS[19][18].append(('町の外でも見通しと警戒を保ち、地上の車の行方を確かめながら進みました。南門を出た怪しい馬車が特定されると、ローゼマインとフェルディナンドは少数の護衛で追跡を始めます。','フェルディナンドと少数の護衛も同行し、地上の車の行方を確かめながら進みました。'))

def revise(n):
    folder = VIDEO / f'本好き_貴族院{n}_ja'
    saved = ROOT / '_temp/novel_dedup_20261003_17_19_original' / folder.name
    data = json.loads((saved / 'scenario.json').read_text(encoding='utf-8-sig'))
    for i,s in enumerate(data['scenes']):
        if i == 21:
            s['long_narration'] = ENDINGS[n]
            continue
        value = s['long_narration']
        marker = CUTS[n][i]
        if marker not in value:
            raise ValueError((n,i,marker))
        value = value[:value.index(marker)].rstrip()
        if i in ADDITIONS[n]:
            anchor,extra = ADDITIONS[n][i]
            if anchor:
                if anchor not in value: raise ValueError((n,i,anchor))
                value = value.replace(anchor,extra+anchor,1)
            else: value += extra
        if i in REPLACEMENTS.get(n,{}):
            s['title'],value=REPLACEMENTS[n][i]
        if n == 19 and i == 2:
            value = value.replace('短い準備期間に全ての属性をそろえた品でした','学生時代に作った全属性の品でした')
        if n == 19 and i == 3:
            value = value.replace('婚約の儀式を無事に終えた翌日','婚約の儀式を無事に終えた後')
        if n == 18 and i == 17:
            value = value.replace('投げやりな婚約準備を','回復薬の引継ぎを')
        for before,after in CLEANUPS.get(n,{}).get(i,[]):
            if before not in value: raise ValueError((n,i,'整理対象なし',before))
            value=value.replace(before,after,1)
        s['long_narration'] = value
        s.update(SCENE_UPDATES.get(n,{}).get(i,{}))
    raw = json.dumps(data,ensure_ascii=False,indent=2)+'\n'
    (folder/'scenario.json').write_text(raw,encoding='utf-8')
    (folder/'scenario.js').write_text('window.SCENARIO = '+raw.rstrip()+';\n',encoding='utf-8')
    path=VIDEO/'本好き__貴族院'/f'本好き__貴族院_{n}.md'
    md=(saved/'source.md').read_text(encoding='utf-8-sig')
    for s in data['scenes']:
        md = re.sub(r'(### '+re.escape(s['id'])+r'\s+)[^\n]*',lambda m:m[1]+s['title'],md)
        pattern=r'(### '+re.escape(s['id'])+r'\b.*?\*\*聞き流し用原稿\*\*：)[^\n]*'
        md,count=re.subn(pattern,lambda m:m[1]+s['long_narration'],md,flags=re.S)
        if count!=1: raise ValueError((n,s['id'],count))
        for label,key in [('一言','short_narration'),('画像イメージ','image_prompt')]:
            pattern=r'(### '+re.escape(s['id'])+r'\b.*?\*\*'+label+r'\*\*：)[^\n]*'
            md=re.sub(pattern,lambda m:m[1]+s[key],md,flags=re.S)
    md=md.replace('テオドールはアンゲリカの弟','テオドールはユーディットの弟')
    path.write_text(md,encoding='utf-8')
    print(n,sum(len(s['long_narration']) for s in data['scenes']))

if __name__=='__main__':
    import sys
    for n in map(int,sys.argv[1:]): revise(n)
